using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Threading;

namespace HuNaoAutoDL.Windows;
public sealed class AppModel : INotifyPropertyChanged, IDisposable
{
    public ObservableCollection<AutoDLInstance> Instances {get;} = new(); public ObservableCollection<ActivityEvent> Activity {get;} = new(); public ObservableCollection<BillRecord> Bills {get;} = new();
    AutoDLInstance? selected; GPUStock? stock; AccountBalance? balance; bool autoStart; bool isBusy; string? error; DispatcherTimer? timer; DateTimeOffset? lastAutoStartAttempt; bool didNotifyLowBalance; bool didNotifyAvailability; public int PollIntervalSeconds { get; private set; } = 15; public double LowBalanceThreshold { get; private set; } = 20; readonly bool demo;
    public bool IsDemo=>demo; public bool IsSignedIn {get; private set;} public AutoDLInstance? Selected {get=>selected;private set{selected=value;OnChanged();}} public GPUStock? Stock{get=>stock;private set{stock=value;OnChanged();}} public AccountBalance? Balance{get=>balance;private set{balance=value;OnChanged();}} public bool AutoStart{get=>autoStart;set{autoStart=value;TokenStore.SavePreferences(PollIntervalSeconds,LowBalanceThreshold,value);OnChanged();}} public bool IsBusy{get=>isBusy;private set{isBusy=value;OnChanged();}} public string? Error{get=>error;private set{error=value;OnChanged();}} public DateTimeOffset? LastUpdated{get;private set;}
    public event PropertyChangedEventHandler? PropertyChanged;
    public event Action<string,string>? NotificationRequested;
    public AppModel(bool demo=false){this.demo=demo;var p=TokenStore.LoadPreferences();PollIntervalSeconds=Math.Clamp(p.PollInterval,8,120);LowBalanceThreshold=Math.Clamp(p.LowBalanceThreshold,1,10000);autoStart=p.AutoStart;if(demo)LoadDemo();else if(TokenStore.Load()!=null){IsSignedIn=true;} }
    public async Task SignInAsync(string token){if(!TokenStore.Save(token)){Error="Token 保存失败";return;}IsSignedIn=true;Error=null;Add("success","已连接 AutoDL","Token 已保存到本机");await RefreshAsync();StartPolling();}
    public void SignOut(){StopPolling();TokenStore.Delete();IsSignedIn=false;Instances.Clear();Bills.Clear();Selected=null;Stock=null;Balance=null;Add("info","已退出登录","");}
    public async Task RefreshAsync(){if(demo){LoadDemo();return;}if(!IsSignedIn||IsBusy)return;var token=TokenStore.Load();if(token==null)return;IsBusy=true;try{using var api=new AutoDLApi(token);var list=await api.FetchInstancesAsync();Instances.Clear();foreach(var i in list)Instances.Add(i);Selected=Instances.FirstOrDefault(x=>x.Id==Selected?.Id) ?? Instances.FirstOrDefault();if(Selected!=null){Stock=await api.FetchGpuStockAsync(Selected);if(Stock.IsAvailable&&!AutoStart&&!didNotifyAvailability){didNotifyAvailability=true;Notify("发现空闲 GPU",$"{Selected.Name} 有 {Stock.IdleGpus} 张 {Selected.GpuName} 空闲");}if(!Stock.IsAvailable)didNotifyAvailability=false;if(AutoStart && Selected.State==InstanceState.Stopped && Stock.IsAvailable && (lastAutoStartAttempt is null || DateTimeOffset.Now-lastAutoStartAttempt > TimeSpan.FromMinutes(1))){lastAutoStartAttempt=DateTimeOffset.Now; await api.PowerOnAsync(Selected.Id); Add("success","自动开机已触发",$"{Selected.Name} · {Stock.IdleGpus} 张空闲 GPU"); Notify("自动开机已触发",$"{Selected.Name} · {Stock.IdleGpus} 张空闲 GPU");}}Balance=await api.FetchBalanceAsync();if(Balance.Available < LowBalanceThreshold&&!didNotifyLowBalance){didNotifyLowBalance=true;Notify("余额不足提醒",$"可用余额 ¥{Balance.Available:0.00}，低于 ¥{LowBalanceThreshold:0.00}");}if(Balance.Available>=LowBalanceThreshold)didNotifyLowBalance=false;try{var bs=await api.FetchBillsAsync(DateTimeOffset.Now.AddDays(-35),DateTimeOffset.Now);Bills.Clear();foreach(var b in bs)Bills.Add(b);}catch{}LastUpdated=DateTimeOffset.Now;Error=null;}catch(AutoDLException ex){Error=ex.Message;if(ex.IsAuth)SignOut();}catch(Exception ex){Error=ex.Message;}finally{IsBusy=false;OnChanged(nameof(LastUpdated));}}
    public async Task TogglePowerAsync(AutoDLInstance i){var token=TokenStore.Load();if(token==null||IsBusy)return;IsBusy=true;try{using var api=new AutoDLApi(token);if(i.State==InstanceState.Stopped){await api.PowerOnAsync(i.Id);Add("success","开机指令已发送",i.Name);}else if(i.State==InstanceState.Running){await api.PowerOffAsync(i.Id);Add("success","关机指令已发送",i.Name);}await Task.Delay(1200);IsBusy=false;await RefreshAsync();}catch(Exception ex){Error=ex.Message;Add("error","操作失败",ex.Message);}finally{IsBusy=false;}}
    public void Select(AutoDLInstance i){Selected=i;_ = RefreshAsync();}
    public void ApplySettings(int intervalSeconds,double threshold){PollIntervalSeconds=Math.Clamp(intervalSeconds,8,120);LowBalanceThreshold=Math.Clamp(threshold,1,10000);TokenStore.SavePreferences(PollIntervalSeconds,LowBalanceThreshold,AutoStart);if(IsSignedIn)StartPolling();OnChanged(nameof(PollIntervalSeconds));OnChanged(nameof(LowBalanceThreshold));} public void StartPolling(){if(demo)return;StopPolling();timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(PollIntervalSeconds)};timer.Tick+=async(_,_)=>await RefreshAsync();timer.Start();}public void StopPolling(){if(timer!=null){timer.Stop();timer=null;}}
    void LoadDemo(){IsSignedIn=true;Instances.Clear();var now=DateTimeOffset.Now;var a=new AutoDLInstance{Id="demo-4090",Name="rtx4090-lab",RawStatus="shutdown",RegionName="北京B区",RegionSign="beijing-b",GpuName="RTX 4090",GpuCount=1,MachineId="seetacloud-4090-07",ChargeType="payg",MemoryTotal=64L*1024*1024*1024,MemoryUsed=7L*1024*1024*1024,SystemDiskTotal=30L*1024*1024*1024,SystemDiskUsed=11L*1024*1024*1024,DataDiskTotal=50L*1024*1024*1024,DataDiskUsed=19L*1024*1024*1024,ReleaseAt=now.AddDays(3)};var b=new AutoDLInstance{Id="demo-a100",Name="a100-train",RawStatus="running",RegionName="内蒙A区",GpuName="A100-SXM4-80GB",GpuCount=1,MachineId="seetacloud-a100-03",ChargeType="payg",MemoryTotal=120L*1024*1024*1024,MemoryUsed=74L*1024*1024*1024,SystemDiskTotal=30L*1024*1024*1024,SystemDiskUsed=18L*1024*1024*1024,DataDiskTotal=50L*1024*1024*1024,DataDiskUsed=36L*1024*1024*1024,ReleaseAt=now.AddDays(12)};Instances.Add(a);Instances.Add(b);var c=new AutoDLInstance{Id="demo-3090",Name="3090-infer",RawStatus="shutdown",RegionName="上海A区",GpuName="RTX 3090",GpuCount=1,MachineId="seetacloud-3090-02",ChargeType="payg",MemoryTotal=32L*1024*1024*1024,MemoryUsed=4L*1024*1024*1024,SystemDiskTotal=30L*1024*1024*1024,SystemDiskUsed=9L*1024*1024*1024,DataDiskTotal=50L*1024*1024*1024,DataDiskUsed=23L*1024*1024*1024,ReleaseAt=now.AddDays(20)};Instances.Add(c);Selected=a;Stock=new(2,8,a.MachineId,a.GpuName,1,now,true);Balance=new(186.4,12.5,30,"balance",now);Bills.Clear();for(int n=0;n<35;n++)Bills.Add(new BillRecord($"demo-{n}",now.AddDays(-n),"charge",5+n%7,"RTX 4090","北京B区",a.MachineId,3600));LastUpdated=now;Add("success","演示数据已加载","离线模式");}
    void Notify(string title,string body)=>NotificationRequested?.Invoke(title,body);
    void Add(string kind,string title,string detail){System.Windows.Application.Current?.Dispatcher.Invoke(()=>{Activity.Insert(0,new ActivityEvent(DateTimeOffset.Now,kind,title,detail));while(Activity.Count>40)Activity.RemoveAt(Activity.Count-1);});}
    void OnChanged([CallerMemberName]string? n=null)=>PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(n)); public void Dispose()=>StopPolling();
}
